sparql:
PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?pub ?title ?year WHERE {
  ?pub dblp:publishedInStream <https://dblp.org/streams/conf/sigmod> .
  ?pub dblp:title ?title .
  ?pub dblp:yearOfPublication ?year .
} ORDER BY DESC(?year)

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?coauthor ?name WHERE {
  <https://dblp.org/pid/l/YannLeCun> dblp:coAuthorWith ?coauthor .
  ?coauthor dblp:creatorName ?name .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT (COUNT(?pub) AS ?count) WHERE {
  ?pub dblp:authoredBy <https://dblp.org/pid/h/JiaweiHan> .
  ?pub dblp:publishedInStream <https://dblp.org/streams/conf/kdd> .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?name ?affiliation WHERE {
  <https://dblp.org/pid/s/MichaelStonebraker> dblp:primaryCreatorName ?name .
  OPTIONAL { <https://dblp.org/pid/s/MichaelStonebraker> dblp:primaryAffiliation ?affiliation }
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?author ?name WHERE {
  ?pub dblp:title "Attention Is All You Need" .
  ?pub dblp:authoredBy ?author .
  ?author dblp:creatorName ?name .
}

PREFIX dblp: <https://dblp.org/rdf/schema#>
SELECT ?journal ?title WHERE {
  ?journal a dblp:Journal .
  ?journal dblp:primaryStreamTitle ?title .
} ORDER BY ?title
